//! hardware-configuration.nix handling.
//!
//! The file describes the machine (disk UUIDs, kernel modules, CPU) and is
//! generated by nixos-generate-config; users should rarely touch it. The
//! system copy is the source of truth:
//!   * this machine: /etc/nixos/hardware-configuration.nix is copied into the
//!     working folder when it is opened (`sync_from_system`), and a build
//!     that would apply a *different* working-copy version needs an explicit
//!     choice (`status` feeds the build dialog).
//!   * remote target: the working copy's file is ignored; the target's own
//!     /etc/nixos/hardware-configuration.nix is fetched over SSH into the
//!     staged copy (see remote.rs, `fetch_target_hardware_script`).
//!
//! A wrong file is the one thing that can leave a machine unbootable (the
//! root/boot/swap UUIDs of another machine), which is why this is strict.

use crate::deploy::ETC_NIXOS;
use crate::types::{HardwarePull, HardwareStatus, HardwareSync, HardwareSyncStatus};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

pub const FILE_NAME: &str = "hardware-configuration.nix";
const SKIP: &[&str] = &[".git", ".claude", "node_modules", "result", "target"];

/// Where the working folder keeps its hardware-configuration.nix, relative to
/// the folder: the root when it is there (or nowhere yet), otherwise the single
/// file of that name found in a subfolder (e.g. hosts/<name>/).
pub fn rel_path_in(workdir: &Path) -> PathBuf {
    if workdir.join(FILE_NAME).is_file() {
        return PathBuf::from(FILE_NAME);
    }
    let mut found: Vec<PathBuf> = Vec::new();
    for entry in walkdir::WalkDir::new(workdir)
        .min_depth(2)
        .max_depth(4)
        .into_iter()
        .filter_entry(|e| !SKIP.contains(&e.file_name().to_string_lossy().as_ref()))
        .flatten()
    {
        if entry.file_type().is_file() && entry.file_name() == FILE_NAME {
            found.push(entry.path().strip_prefix(workdir).unwrap().to_path_buf());
        }
    }
    if found.len() == 1 {
        found.remove(0)
    } else {
        PathBuf::from(FILE_NAME)
    }
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

/// True when the working copy's file is still exactly the one recorded as
/// copied from a deploy target.
pub fn is_pulled_copy(workdir: &Path, pull: Option<&HardwarePull>) -> bool {
    match pull {
        Some(p) => std::fs::read(workdir.join(rel_path_in(workdir))).map(|b| sha256_hex(&b) == p.sha256).unwrap_or(false),
        None => false,
    }
}

/// Copy this machine's hardware-configuration.nix into the working folder
/// (creating or replacing it). Called when a folder is opened. A file that
/// was copied from a deploy target (`pull`, hash still matching) is kept.
pub fn sync_from_system(workdir: &Path, pull: Option<&HardwarePull>) -> HardwareSync {
    sync_inner(workdir, &Path::new(ETC_NIXOS).join(FILE_NAME), pull)
}

fn sync_inner(workdir: &Path, system_file: &Path, pull: Option<&HardwarePull>) -> HardwareSync {
    let rel = rel_path_in(workdir);
    let rel_s = rel.to_string_lossy().to_string();
    let done = |status: HardwareSyncStatus, message: String| HardwareSync { status, rel_path: rel_s.clone(), message };
    if same_dir(workdir, Path::new(ETC_NIXOS)) {
        return done(HardwareSyncStatus::Skipped, "the working folder is /etc/nixos itself".into());
    }
    if let Some(p) = pull.filter(|p| is_pulled_copy(workdir, Some(p))) {
        return done(HardwareSyncStatus::FromTarget, format!("{rel_s} is the copy taken from target '{}' on {}; kept (not replaced by this machine's)", p.target, p.at.chars().take(10).collect::<String>()));
    }
    let system = match std::fs::read(system_file) {
        Ok(b) => b,
        Err(_) => return done(HardwareSyncStatus::NoSystemFile, format!("{} has no {FILE_NAME}; nothing copied", system_file.parent().map(|p| p.display().to_string()).unwrap_or_default())),
    };
    let dest = workdir.join(&rel);
    match std::fs::read(&dest) {
        Ok(local) if local == system => done(HardwareSyncStatus::Unchanged, format!("{rel_s} matches the system copy")),
        Ok(_) => match write(&dest, &system) {
            Ok(()) => done(HardwareSyncStatus::Refreshed, format!("{rel_s} replaced with the system copy from /etc/nixos (it differed)")),
            Err(e) => done(HardwareSyncStatus::NotWritable, format!("could not replace {rel_s}: {e}")),
        },
        Err(_) => match write(&dest, &system) {
            Ok(()) => done(HardwareSyncStatus::Copied, format!("{rel_s} copied from /etc/nixos")),
            Err(e) => done(HardwareSyncStatus::NotWritable, format!("could not write {rel_s}: {e}")),
        },
    }
}

fn write(dest: &Path, bytes: &[u8]) -> std::io::Result<()> {
    if let Some(p) = dest.parent() {
        std::fs::create_dir_all(p)?;
    }
    std::fs::write(dest, bytes)
}

fn same_dir(a: &Path, b: &Path) -> bool {
    match (std::fs::canonicalize(a), std::fs::canonicalize(b)) {
        (Ok(x), Ok(y)) => x == y,
        _ => false,
    }
}

/// Compare the working folder's file with the system copy (for the build
/// dialog on this machine).
pub fn status(workdir: &Path, pull: Option<&HardwarePull>) -> HardwareStatus {
    status_inner(workdir, &Path::new(ETC_NIXOS).join(FILE_NAME), pull)
}

fn status_inner(workdir: &Path, system_file: &Path, pull: Option<&HardwarePull>) -> HardwareStatus {
    let rel = rel_path_in(workdir);
    let system = std::fs::read_to_string(system_file).ok();
    let local = std::fs::read_to_string(workdir.join(&rel)).ok();
    let (differs, unified_diff) = match (&system, &local) {
        (Some(s), Some(l)) if s != l => {
            let diff = similar::TextDiff::from_lines(s.as_str(), l.as_str())
                .unified_diff()
                .context_radius(3)
                .header(&format!("/etc/nixos/{FILE_NAME}"), &format!("working copy {}", rel.display()))
                .to_string();
            (true, Some(diff))
        }
        _ => (false, None),
    };
    let pulled_from = pull.filter(|p| is_pulled_copy(workdir, Some(p))).cloned();
    HardwareStatus { system_exists: system.is_some(), local_exists: local.is_some(), rel_path: rel.to_string_lossy().to_string(), differs, unified_diff, pulled_from }
}

/// Write a file fetched from a deploy target over the working folder's
/// hardware-configuration.nix and return the record to remember it by.
pub fn install_pulled(workdir: &Path, target: &str, text: &str) -> std::io::Result<(PathBuf, HardwarePull)> {
    let rel = rel_path_in(workdir);
    write(&workdir.join(&rel), text.as_bytes())?;
    let pull = HardwarePull { target: target.to_string(), sha256: sha256_hex(text.as_bytes()), at: chrono::Utc::now().to_rfc3339() };
    Ok((rel, pull))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp(name: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("nm-hw-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        d
    }

    #[test]
    fn sync_copies_refreshes_and_leaves_alone() {
        let d = tmp("sync");
        let sys = d.join("etc").join(FILE_NAME);
        std::fs::create_dir_all(sys.parent().unwrap()).unwrap();
        std::fs::write(&sys, "{ fileSystems.\"/\".device = \"/dev/disk/by-uuid/AAA\"; }\n").unwrap();
        let work = d.join("work");
        std::fs::create_dir_all(&work).unwrap();
        std::fs::write(work.join("flake.nix"), "{}").unwrap();

        let r = sync_inner(&work, &sys, None);
        assert!(matches!(r.status, HardwareSyncStatus::Copied), "{r:?}");
        assert_eq!(std::fs::read(work.join(FILE_NAME)).unwrap(), std::fs::read(&sys).unwrap());

        let r = sync_inner(&work, &sys, None);
        assert!(matches!(r.status, HardwareSyncStatus::Unchanged), "{r:?}");

        std::fs::write(work.join(FILE_NAME), "# edited by hand\n").unwrap();
        let st = status_inner(&work, &sys, None);
        assert!(st.differs && st.unified_diff.as_deref().unwrap().contains("by-uuid/AAA"));
        let r = sync_inner(&work, &sys, None);
        assert!(matches!(r.status, HardwareSyncStatus::Refreshed), "{r:?}");
        assert_eq!(std::fs::read(work.join(FILE_NAME)).unwrap(), std::fs::read(&sys).unwrap());
        assert!(!status_inner(&work, &sys, None).differs);

        let r = sync_inner(&work, &d.join("missing").join(FILE_NAME), None);
        assert!(matches!(r.status, HardwareSyncStatus::NoSystemFile), "{r:?}");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn pulled_copy_survives_sync_until_edited() {
        let d = tmp("pull");
        let sys = d.join("etc").join(FILE_NAME);
        std::fs::create_dir_all(sys.parent().unwrap()).unwrap();
        std::fs::write(&sys, "desktop\n").unwrap();
        let work = d.join("work");
        std::fs::create_dir_all(&work).unwrap();
        let (rel, pull) = install_pulled(&work, "lg-laptop", "laptop disks\n").unwrap();
        assert_eq!(rel, PathBuf::from(FILE_NAME));
        assert_eq!(pull.target, "lg-laptop");
        // sync on open keeps it
        let r = sync_inner(&work, &sys, Some(&pull));
        assert!(matches!(r.status, HardwareSyncStatus::FromTarget), "{r:?}");
        assert_eq!(std::fs::read_to_string(work.join(FILE_NAME)).unwrap(), "laptop disks\n");
        let st = status_inner(&work, &sys, Some(&pull));
        assert!(st.differs && st.pulled_from.as_ref().map(|p| p.target.as_str()) == Some("lg-laptop"));
        // once edited it is an ordinary (drifted) file again → the system copy wins
        std::fs::write(work.join(FILE_NAME), "laptop disks, edited\n").unwrap();
        assert!(status_inner(&work, &sys, Some(&pull)).pulled_from.is_none());
        let r = sync_inner(&work, &sys, Some(&pull));
        assert!(matches!(r.status, HardwareSyncStatus::Refreshed), "{r:?}");
        assert_eq!(std::fs::read_to_string(work.join(FILE_NAME)).unwrap(), "desktop\n");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn file_in_subfolder_is_found_and_used() {
        let d = tmp("sub");
        let sys = d.join("etc").join(FILE_NAME);
        std::fs::create_dir_all(sys.parent().unwrap()).unwrap();
        std::fs::write(&sys, "sys\n").unwrap();
        let work = d.join("work");
        std::fs::create_dir_all(work.join("hosts").join("laptop")).unwrap();
        std::fs::write(work.join("hosts").join("laptop").join(FILE_NAME), "old\n").unwrap();
        assert_eq!(rel_path_in(&work), PathBuf::from("hosts/laptop").join(FILE_NAME));
        let r = sync_inner(&work, &sys, None);
        assert!(matches!(r.status, HardwareSyncStatus::Refreshed), "{r:?}");
        assert_eq!(std::fs::read_to_string(work.join("hosts/laptop").join(FILE_NAME)).unwrap(), "sys\n");
        assert!(!work.join(FILE_NAME).exists(), "must not create a second copy at the root");
        // two candidates → ambiguous → root
        std::fs::create_dir_all(work.join("hosts").join("desktop")).unwrap();
        std::fs::write(work.join("hosts").join("desktop").join(FILE_NAME), "x\n").unwrap();
        assert_eq!(rel_path_in(&work), PathBuf::from(FILE_NAME));
        let _ = std::fs::remove_dir_all(&d);
    }
}
